1	// Package api is the product's JSON HTTP API.
2	package api
3	
4	import (
5		"encoding/json"
6		"errors"
7		"net/http"
8		"time"
9	
10		"example.com/saasapi/internal/billing"
11		"example.com/saasapi/internal/store"
12	)
13	
14	// Options configure a Server.
15	type Options struct {
16		// Now is the server's clock; nil means time.Now. Tests set it to move time without sleeping.
17		Now func() time.Time
18	}
19	
20	// Server serves the API.
21	type Server struct {
22		store *store.Store
23		now   func() time.Time
24		mux   *http.ServeMux
25	}
26	
27	// New returns a server over a store.
28	func New(st *store.Store, opt Options) *Server {
29		s := &Server{store: st, now: opt.Now, mux: http.NewServeMux()}
30		if s.now == nil {
31			s.now = time.Now
32		}
33		s.mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
34			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
35		})
36		s.mux.HandleFunc("GET /api/customers", s.authed(s.listCustomers))
37		s.mux.HandleFunc("POST /api/customers", s.authed(s.createCustomer))
38		s.mux.HandleFunc("GET /api/customers/{id}", s.authed(s.getCustomer))
39		s.mux.HandleFunc("GET /api/invoices", s.authed(s.listInvoices))
40		s.mux.HandleFunc("POST /api/invoices", s.authed(s.createInvoice))
41		s.mux.HandleFunc("GET /api/invoices/{id}", s.authed(s.getInvoice))
42		return s
43	}
44	
45	// ServeHTTP implements http.Handler.
46	func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) { s.mux.ServeHTTP(w, r) }
47	
48	// handler is an endpoint that runs for a known account.
49	type handler func(w http.ResponseWriter, r *http.Request, acct store.Account)
50	
51	// authed resolves the X-API-Key header to its account, or answers 401.
52	func (s *Server) authed(h handler) http.HandlerFunc {
53		return func(w http.ResponseWriter, r *http.Request) {
54			acct, ok := s.store.AccountForKey(r.Header.Get("X-API-Key"))
55			if !ok {
56				writeError(w, http.StatusUnauthorized, "unauthorized")
57				return
58			}
59			h(w, r, acct)
60		}
61	}
62	
63	func (s *Server) listCustomers(w http.ResponseWriter, r *http.Request, acct store.Account) {
64		writeJSON(w, http.StatusOK, map[string]any{"items": s.store.Customers(acct.ID)})
65	}
66	
67	func (s *Server) createCustomer(w http.ResponseWriter, r *http.Request, acct store.Account) {
68		var in struct {
69			Name  string     `json:"name"`
70			Email string     `json:"email"`
71			Plan  store.Plan `json:"plan"`
72		}
73		if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
74			writeError(w, http.StatusBadRequest, "invalid_json")
75			return
76		}
77		c, err := s.store.CreateCustomer(acct.ID, in.Name, in.Email, in.Plan, s.now())
78		if err != nil {
79			writeStoreError(w, err)
80			return
81		}
82		writeJSON(w, http.StatusCreated, c)
83	}
84	
85	func (s *Server) getCustomer(w http.ResponseWriter, r *http.Request, acct store.Account) {
86		c, ok := s.store.Customer(acct.ID, r.PathValue("id"))
87		if !ok {
88			writeError(w, http.StatusNotFound, "not_found")
89			return
90		}
91		writeJSON(w, http.StatusOK, c)
92	}
93	
94	// invoiceView is an invoice with its totals.
95	type invoiceView struct {
96		store.Invoice
97		Totals billing.Totals `json:"totals"`
98	}
99	
100	func view(inv store.Invoice) invoiceView {
101		return invoiceView{Invoice: inv, Totals: billing.Compute(inv)}
102	}
103	
104	func (s *Server) listInvoices(w http.ResponseWriter, r *http.Request, acct store.Account) {
105		items := []invoiceView{}
106		for _, inv := range s.store.Invoices(acct.ID) {
107			items = append(items, view(inv))
108		}
109		writeJSON(w, http.StatusOK, map[string]any{"items": items})
110	}
111	
112	func (s *Server) createInvoice(w http.ResponseWriter, r *http.Request, acct store.Account) {
113		var in struct {
114			CustomerID    string           `json:"customer_id"`
115			Lines         []store.LineItem `json:"lines"`
116			CouponPercent int              `json:"coupon_percent"`
117			CreditCents   int64            `json:"credit_cents"`
118		}
119		if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
120			writeError(w, http.StatusBadRequest, "invalid_json")
121			return
122		}
123		inv, err := s.store.CreateInvoice(store.Invoice{AccountID: acct.ID, CustomerID: in.CustomerID, Lines: in.Lines, CouponPercent: in.CouponPercent, CreditCents: in.CreditCents}, s.now())
124		if err != nil {
125			writeStoreError(w, err)
126			return
127		}
128		writeJSON(w, http.StatusCreated, view(inv))
129	}
130	
131	func (s *Server) getInvoice(w http.ResponseWriter, r *http.Request, acct store.Account) {
132		inv, ok := s.store.Invoice(acct.ID, r.PathValue("id"))
133		if !ok {
134			writeError(w, http.StatusNotFound, "not_found")
135			return
136		}
137		writeJSON(w, http.StatusOK, view(inv))
138	}
139	
140	func writeJSON(w http.ResponseWriter, status int, v any) {
141		w.Header().Set("Content-Type", "application/json")
142		w.WriteHeader(status)
143		_ = json.NewEncoder(w).Encode(v)
144	}
145	
146	// writeError answers {"error": code}.
147	func writeError(w http.ResponseWriter, status int, code string) {
148		writeJSON(w, status, map[string]string{"error": code})
149	}
150	
151	func writeStoreError(w http.ResponseWriter, err error) {
152		switch {
153		case errors.Is(err, store.ErrNotFound):
154			writeError(w, http.StatusNotFound, "not_found")
155		case errors.Is(err, store.ErrInvalid):
156			writeError(w, http.StatusUnprocessableEntity, "invalid")
157		default:
158			writeError(w, http.StatusInternalServerError, "internal")
159		}
160	}
