// authed resolves the X-API-Key header to its account, or answers 401.
// A known key is rate limited by its own count; rejected requests answer 429.
func (s *Server) authed(h handler) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		key := r.Header.Get("X-API-Key")
		acct, ok := s.store.AccountForKey(key)
		if !ok {
			writeError(w, http.StatusUnauthorized, "unauthorized")
			return
		}
		if allowed, retryAfter := s.limits.allow(key, limitFor(acct.Plan)); !allowed {
			w.Header().Set("Retry-After", strconv.Itoa(retryAfter))
			writeError(w, http.StatusTooManyRequests, "rate_limited")
			return
		}
		h(w, r, acct)

